    "Las vinculaciones de políticas, la identidad de carga de trabajo, los alcances, el vencimiento del permiso, los métodos de autenticación, las sesiones y los recibos de auditoría siguen disponibles abajo.",
  "secrets.route.accessAction": "Conceder acceso",
  "secrets.route.developerAnswer": "Elija un secreto, revise exactamente cómo lo leerá una aplicación y luego pruebe el acceso sin mostrar el valor.",
  "secrets.route.developerDetails":
    "Antes de ejecutar la prueba, el servidor comprueba el tenant, el permiso, la versión actual, las referencias opcionales, los argumentos de CLI, la ruta de API, la recuperación y el límite de manejo del valor.",
  "secrets.route.developerAction": "Planificar acceso",
  "secrets.route.sharingAnswer": "Qué se puede ver una vez, quién puede verlo y hasta cuándo.",
  "secrets.route.sharingDetails":
    "Para canjear un secreto se requieren el token y acceso secrets:read en el mismo tenant. Caduca al canjearlo o al vencer el plazo; no se puede cancelar una entrega individual. Las credenciales temporales de máquinas tienen controles de revocación separados.",
  "secrets.route.sharingAction": "Crear secreto compartido de un solo uso",
  "secrets.route.enginesAnswer": "Qué sistemas pueden crear credenciales de corta duración bajo demanda.",
  "secrets.route.enginesDetails":
    "La configuración del proveedor, la custodia de claves de certificados, la duración del permiso, la renovación, la revocación, el cifrado de tránsito, HMAC y la firma siguen disponibles abajo.",
  "secrets.route.enginesAction": "Añadir fuente",
  "secrets.route.scanningAnswer": "Qué repositorios se revisaron y qué debe eliminarse.",
  "secrets.route.scanningDetails":
    "Las reglas del escáner, las ubicaciones de evidencia redactadas, los webhooks del proveedor, la importación de artefactos, las supresiones y el historial de ejecuciones siguen disponibles abajo.",
  "secrets.route.scanningAction": "Conectar repositorio",
