  "discovery.coverage.help":
    "La cobertura se mide frente a los segmentos que usted declaró, no frente a lo que el descubrimiento encontró por casualidad: un inventario construido solo a partir de hallazgos puede describir lo que encontró y nada más. Los segmentos excluidos quedan fuera de ambas mitades en lugar de contarse como cubiertos. Un certificado sin observación detrás es prueba de una emisión, no de un despliegue.",
