  "source.deployment.truth.help.d3tri00002":
    "\u00abEntregado\u00bb es el relato de este plano de control sobre lo que hizo. \u00abVerificado\u00bb es lo que un cliente obtiene realmente, establecido mediante un handshake TLS contra el extremo. Una renovaci\u00f3n puede entregarse y no llegar nunca, por eso se cuentan por separado y no se suman.",
