  "source.never.b3wla0012": "Nunca",
  "source.endpoint.key.custody.b2cus00001": "Custodia de claves por destino",
  "source.endpoint.key.custody.help.b2cus00002":
    "Para cada destino de despliegue, qu\u00e9 proceso genera la clave privada. Un destino marcado como executor=agent genera su clave en el host que la sirve, y este plano de control se niega a enviarle material de clave. Los dem\u00e1s destinos usan la ruta del plano de control, que funciona: es la migraci\u00f3n pendiente, no un defecto.",
  "source.endpoint.key.custody.summary.b2cus00003": "{value1} de {value2} destinos generan claves en el host ({value3}%).",
  "source.endpoint.key.custody.caption.b2cus00004": "Destinos de despliegue y d\u00f3nde se generan sus claves privadas",
  "source.target.b2cus00005": "Destino",
