  "source.endpoint.verification.d2ver00001": "Verificaci\u00f3n de extremos",
  "source.endpoint.verification.help.d2ver00002":
    "Cada fila es un handshake TLS que alguien realiz\u00f3, no un registro de lo que hizo este plano de control. Una renovaci\u00f3n puede tener \u00e9xito en la AC, ser entregada por un conector y no llegar nunca al listener, mientras cada recibo de entrega sigue en verde y los clientes siguen recibiendo el certificado antiguo.",
