  "source.custody.unrecorded.b5cust0002":
    "Este registro no permite determinar dónde se creó la clave privada ni cómo se protege. No se ha registrado el motivo de la falta de pruebas. No registrado no significa seguro.",
  "source.status.920e413c7d": "Estado",
